import { Pool } from 'pg';
const pool = new Pool();

async function getRoomsVisibility(roomIds: string[]) {
  const list = `('${roomIds.join("','")}')`;
  const res = await pool.query(
    `SELECT room_id, visibility FROM room_visibility WHERE room_id IN ${list}`
  );
  return res.rows;
}

async function sync() {
  const rooms = await pool.query('SELECT room_id FROM rooms');
  await getRoomsVisibility(rooms.rows.map((r) => r.room_id));
}

import { exec } from './util/exec';

function helmCommands(config: any) {
  const cmd: string[] = [];
  for (const name of Object.keys(config.registryAliases || {})) {
    const url = config.registryAliases[name];
    cmd.push(`helm repo add ${name} ${url} --force-update`);
  }
  return exec(cmd, {});
}

import { exec } from './util/exec';

async function updateLock(deps: { depName?: string }[]) {
  const packagesToUpdate = deps.map((d) => d.depName).filter(Boolean);
  const updateCommand = ['gleam deps update', ...packagesToUpdate].join(' ');
  return exec(updateCommand, {});
}

const { Bash } = require('node-bash');

