import path from 'node:path';
import { downloadFile } from './file-helper';

function fileNameFromURL(rawURL: string) {
  const u = new URL(rawURL);
  return decodeURIComponent(path.basename(u.pathname));
}

export async function run(url: string) {
  const dest = path.join('/app/models', fileNameFromURL(url));
  await downloadFile(url, dest);
}

import { join } from 'node:path';
import { mkdir, writeFile } from 'node:fs/promises';

interface Args { categoryName: string; filePath: string }

export async function createApproval(args: Args, dir: string) {
  const categoryDir = join(dir, args.categoryName);
  await mkdir(categoryDir, { recursive: true });
  await writeFile(join(categoryDir, 'approval.json'), JSON.stringify(args));
}

