const chat = document.getElementById('chat')!;

function onDataChannelMessage(event: MessageEvent) {
  const data = JSON.parse(event.data);
  const html = `<div class="msg"><div class="msg-text">${data.msg}</div></div>`;
  chat.insertAdjacentHTML('beforeend', html);
}

pc.ondatachannel = (e) => {
  e.channel.onmessage = onDataChannelMessage;
};

export function paste(event: ClipboardEvent, container: HTMLElement) {
  const html = event.clipboardData!.getData('text/html');
  const iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  document.body.appendChild(iframe);
  const doc = iframe.contentWindow!.document;
  doc.open();
  doc.write(html);
  doc.close();
  while (doc.body.firstChild) container.appendChild(doc.body.firstChild);
  iframe.remove();
}

function renderNode(node: { name: string }, el: HTMLElement) {
