import path from 'node:path';
import fs from 'node:fs';

interface Args { output_name?: string }

export function screenshot(args: Args, refDir: string) {
  const name = args.output_name || 'shot';
  const file = path.join(refDir, `element_${name}.png`);
  fs.writeFileSync(file, Buffer.from('png'));
}

function linkURLs(text: string) {
  return text.replace(/(https?:\/\/\S+)/g, '<a href="$1">$1</a>');
}

function appendLine(text: string) {
  const span = document.createElement('span');
  span.innerHTML = linkURLs(text);
  document.getElementById('chat')!.appendChild(span);
}

socket.on('instantMessage', (data) => appendLine(data.Message));

function renderExif(el: HTMLElement, data: any) {
  let html = '<table class="exif">';
  for (const item of data.photo.exif) {
    const value = item.clean ? item.clean._content : item.raw._content;
    html += '<tr><td>' + item.label + '</td><td>' + value + '</td></tr>';
  }
  html += '</table>';
  el.innerHTML = html;
}

api.getExif(photoId, (data) => renderExif(el, data));

